<script setup lang="ts">
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import ListPanel from '../components/ListPanel.vue';
import {computed,onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import { Search } from 'lucide-vue-next';import {api} from '../api';import {dateText,errorText} from '../saas';import ProvincePageState from '../components/ProvincePageState.vue';import ProvinceEntityDrawer from '../components/ProvinceEntityDrawer.vue';import './ProvincePages.css';
const route=useRoute(),router=useRouter(),type=ref(String(route.query.type??'ENTERPRISE')),eventType=ref(['ALERT','ACCIDENT','VIOLATION'].includes(String(route.query.eventType))?String(route.query.eventType):'ALERT'),workspaceId=ref(String(route.query.workspaceId??'')),q=ref(String(route.query.q??'')),page=ref(1),rows=ref<any[]>([]),workspaces=ref<any[]>([]),total=ref(0),loading=ref(false),error=ref(''),drawer=ref(false),selected=ref<any>(null);let generation=0;
const typeNames:Record<string,string>={ENTERPRISE:'企业',VEHICLE:'车辆',LICENSE:'许可',INCIDENT:'安全事件'};const endpoints:Record<string,string>={ENTERPRISE:'/archives/enterprises',VEHICLE:'/archives/vehicles',LICENSE:'/admission/licenses',ALERT:'/safety/alerts',ACCIDENT:'/safety/accidents',VIOLATION:'/safety/violations'};const detailKind=computed(()=>type.value==='INCIDENT'?eventType.value:type.value);const statusLabels:Record<string,string>={ACTIVE:'有效',INACTIVE:'已停用',VALID:'有效',EXPIRED:'已到期',SUSPENDED:'暂停',CANCELLED:'已注销',PENDING_CONFIRMATION:'待确认',PROCESSING:'处理中',PENDING_REVIEW:'待复核',CLOSED:'已闭环',REPORTED:'已上报',ARCHIVED:'已归档',RECTIFYING:'整改中',CONFIRMED:'已认定',PENDING_DETERMINATION:'待认定'};
async function load(){const version=++generation;loading.value=true;error.value='';const params=new URLSearchParams({page:String(page.value),pageSize:'20'});if(q.value.trim())params.set('q',q.value.trim());if(workspaceId.value)params.set('workspaceId',workspaceId.value);try{if(!workspaces.value.length)workspaces.value=(await api<any>('/oversight/options')).workspaces;const r=await api<any>(`${endpoints[detailKind.value]}?${params}`);if(version===generation){rows.value=r.items;total.value=r.total}}catch(e){if(version===generation)error.value=errorText(e)}finally{if(version===generation)loading.value=false}}
function search(){page.value=1;router.replace({path:route.path,query:{type:type.value,...(q.value.trim()?{q:q.value.trim()}:{}),...(workspaceId.value?{workspaceId:workspaceId.value}:{}),...(type.value==='INCIDENT'?{eventType:eventType.value}:{})}});load()}function open(row:any){selected.value=row;drawer.value=true}
onMounted(async()=>{if(!typeNames[type.value])type.value='ENTERPRISE';try{workspaces.value=(await api<any>('/oversight/options')).workspaces}catch(e){error.value=errorText(e);return}await load();if(typeof route.query.entityId==='string'){if(type.value==='LICENSE'){try{const p=new URLSearchParams({id:route.query.entityId,pageSize:'1'});if(workspaceId.value)p.set('workspaceId',workspaceId.value);const r=await api<any>(`/admission/licenses?${p}`);const item=r.items.find((x:any)=>x.id===route.query.entityId);if(item)open(item);else error.value='该许可不存在或不在当前查询范围内'}catch(e){error.value=errorText(e)}}else open({id:route.query.entityId})}});

function resetQueryFilters() {
  workspaceId.value = '';
  q.value = '';
  page.value = 1;
  search();
}
</script>
<template><section class="province-page"><h1 class="sr-only">综合查询</h1><QueryPanel :loading="loading" @search="search" @reset="resetQueryFilters">
<QueryField label="查询对象"><el-select aria-label="查询对象" v-model="type" placeholder="查询对象" @change="search"><el-option v-for="(name,key) in typeNames" :key="key" :label="name" :value="key"/></el-select></QueryField>
<QueryField label="事件类型" v-if="type==='INCIDENT'"><el-select aria-label="事件类型"  v-model="eventType" @change="search"><el-option label="风险告警" value="ALERT"/><el-option label="事故" value="ACCIDENT"/><el-option label="违规" value="VIOLATION"/></el-select></QueryField>
<QueryField label="城市"><el-select aria-label="城市" v-model="workspaceId" clearable placeholder="全部城市" @change="search"><el-option v-for="o in workspaces" :key="o.id" :label="o.cityName" :value="o.id"/></el-select></QueryField>
<QueryField label="关键词" keyword><el-input aria-label="关键词" v-model="q" :prefix-icon="Search" clearable :placeholder="`搜索${typeNames[type]}名称或编号`" /></QueryField>
</QueryPanel>
<ListPanel title="综合查询结果" :total="error ? undefined : (total)">
<ProvincePageState :error="error" :loading="loading" @retry="load"><el-table :data="rows" row-key="id" empty-text="未找到符合条件的业务对象"><el-table-column :label="`${typeNames[type]}对象`" min-width="260"><template #default="{row}"><div class="province-cell-title"><strong>{{row.name??row.title??row.licenseNo}}</strong><span>{{row.businessNo}}</span></div></template></el-table-column><el-table-column v-if="type==='ENTERPRISE'" prop="creditCode" label="统一社会信用代码" min-width="190"/><el-table-column v-if="type==='VEHICLE'" label="车辆编码" min-width="190"><template #default="{row}">{{row.unifiedCode??row.vin}}</template></el-table-column><el-table-column v-if="type!=='ENTERPRISE'" label="所属企业" min-width="220"><template #default="{row}">{{row.enterprise?.name??'—'}}</template></el-table-column><el-table-column label="所属机构" min-width="170"><template #default="{row}">{{row.organization?.name??'—'}}</template></el-table-column><el-table-column label="状态" width="115"><template #default="{row}"><el-tag effect="plain" :type="['ACTIVE','VALID','CLOSED'].includes(row.status)?'success':'info'">{{statusLabels[row.status]??row.status}}</el-tag></template></el-table-column><el-table-column :label="type==='INCIDENT'?'发生时间':type==='LICENSE'?'有效期至':'更新时间'" width="175"><template #default="{row}">{{dateText(type==='INCIDENT'?row.occurredAt:type==='LICENSE'?row.expiresAt:row.updatedAt)}}</template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">详情</el-button></template></el-table-column></el-table><div class="province-pagination"><span>共 {{total}} 个{{typeNames[type]}}对象</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/></div></ProvincePageState>
</ListPanel>
<ProvinceEntityDrawer v-model="drawer" :kind="detailKind" :row="selected"/></section></template>
